mapper.select:
SELECT dd.food_name AS foodName, COUNT(*) AS eatCount FROM diet_details dd INNER JOIN diet_records dr ON dd.diet_id = dr.diet_id WHERE dr.eat_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) AND dr.deleted_at IS NULL
AND dr.meal_type = #{mealType}
GROUP BY dd.food_name ORDER BY eatCount DESC LIMIT 10
